/*
 * Empty stand-ins for two tables of the release builds' generated code.
 *
 * The code the release builds are made from was generated by an earlier
 * discovery pass, and two files beside it hold functions that pass missed,
 * lifted one at a time: recomp_seeded.c (functions named only in vtables and
 * state-handler tables) and recomp_holes.c (functions reached by direct calls
 * and tail jumps). recomp_manual.c looks them up by address before the
 * generated dispatch table.
 *
 * Code generated with today's tools/recomp finds those functions in its
 * ordinary pass and writes neither file. port/CMakeLists.txt then compiles
 * this one in their place, with JSRF_NO_SEEDED and/or JSRF_NO_HOLES, so the
 * build links and the lookups find nothing.
 */
#include <stdint.h>

typedef void (*recomp_table_func_t)(void);

#ifdef JSRF_NO_SEEDED
const struct { uint32_t va; recomp_table_func_t fn; } g_recomp_seeded[1] = { { 0, 0 } };
const unsigned g_recomp_seeded_count = 0;
#endif

#ifdef JSRF_NO_HOLES
const struct { uint32_t va; recomp_table_func_t fn; } g_recomp_holes[1] = { { 0, 0 } };
const unsigned g_recomp_holes_count = 0;
#endif
